def transform(grid):
    h, w = len(grid), len(grid[0])
    diag = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                d = c-r
                if d in diag and diag[d] != v:
                    raise ValueError('inconsistent diagonal')
                diag[d] = v
    # Infer diagonal period from repetition of observed colored stripes.
    # Use the smallest period for which all observed offset/color assignments agree.
    offsets = sorted(diag)
    candidates=[]
    for p in range(1, max(h,w)*2+1):
        if all(diag[a] == diag[b] for a in offsets for b in offsets if (a-b)%p==0):
            candidates.append(p)
    # sequence may be an arbitrary primitive motif; detect its period from the span of known diagonal runs.
    # Fallback to the inferred stripe-cycle length encoded by distinct diagonal offsets.
    p = candidates[0] if candidates else (max(offsets)-min(offsets)+1)
    # For sparse motifs with distinct colors, the offsets are anchors in one cycle. Determine period
    # from the total extent of the diagonal arrangement (usually the grid's width minus line spacing).
    if len(candidates)==0:
        p = max(1, max(offsets)-min(offsets)+1)
    out=[]
    for r in range(h):
        row=[]
        for c in range(w):
            d=c-r
            known=[(abs(d-k), k, v) for k,v in diag.items()]
            # Extend the motif cyclically: use offset congruent under period where known.
            matches=[v for k,v in diag.items() if (d-k)%p==0]
            row.append(matches[0] if matches else 0)
        out.append(row)
    return out
