def transform(grid):
    h, w = len(grid), len(grid[0])
    stripes = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in stripes and stripes[d] != color:
                    raise ValueError('inconsistent stripe')
                stripes[d] = color
    if not stripes:
        return [row[:] for row in grid]
    # Infer the shortest period in the diagonal stripe colors.
    period = next(p for p in range(1, 2 * max(h, w) + 1)
                  if all(a % p != b % p or ca == cb
                         for a, ca in stripes.items()
                         for b, cb in stripes.items()))
    by_residue = {d % period: color for d, color in stripes.items()}
    if len(by_residue) != period:
        raise ValueError('stripe cycle is underdetermined')
    return [[by_residue[(c-r) % period] for c in range(w)] for r in range(h)]
